1	import { db } from "./db";
2	import { ovh, ovhApi, ovhConfigured } from "./ovh";
3	
4	const SERVER = process.env.OVH_SERVER_NAME ?? "ns5002569.ip-51-79-162.net";
5	/** Monthly price the customer pays for a dedicated IPv4 (OVH cost ~$2.39 + margin). */
6	export const DEDICATED_IP_PRICE_CENTS = Number(process.env.DEDICATED_IP_PRICE_CENTS ?? 399);
7	/** Keep this many spare IPs in the pool; auto-order/release aims to stay near it. */
8	export const DEDICATED_IP_BUFFER = Number(process.env.DEDICATED_IP_BUFFER ?? 2);
9	
10	/** OVH failover gateway = the host's /24 gateway (…​.254). */
11	export function ovhGateway(): string {
12	  const ip = process.env.PUBLIC_IP ?? "51.79.162.96";
13	  const parts = ip.split(".");
14	  return `${parts[0]}.${parts[1]}.${parts[2]}.254`;
15	}
16	
17	/**
18	 * Pull additional/failover IPv4 addresses routed to our server from OVH and
19	 * upsert them into the pool. The host's own primary IP is never poolable.
20	 */
21	export async function syncDedicatedIpPool(): Promise<{ imported: number; total: number }> {
22	  if (!ovhConfigured()) return { imported: 0, total: 0 };
23	  const primary = process.env.PUBLIC_IP;
24	  const blocks: string[] = await ovhApi.ips();
25	  let imported = 0;
26	  for (const block of blocks) {
27	    if (block.includes(":")) continue; // IPv6 handled separately
28	    let info: any;
29	    try {
30	      info = await ovhApi.ipInfo(block);
31	    } catch {
32	      continue;
33	    }
34	    if (info?.routedTo?.serviceName !== SERVER) continue;
35	    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
36	    // A /32 block is a single usable IP == the block minus the mask.
37	    const address = block.split("/")[0];
38	    if (address === primary) continue;
39	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
40	    if (!existing) {
41	      await db.dedicatedIp.create({ data: { address, ovhBlock: block, status: "FREE" } });
42	      imported++;
43	    }
44	  }
45	  const total = await db.dedicatedIp.count();
46	  return { imported, total };
47	}
48	
49	export async function freeCount(): Promise<number> {
50	  return db.dedicatedIp.count({ where: { status: "FREE" } });
51	}
52	
53	/** Find the OVH Virtual MAC currently bound to an IP, if any. */
54	async function findVirtualMacForIp(address: string): Promise<string | null> {
55	  const macs: string[] = await ovh("GET", `/dedicated/server/${SERVER}/virtualMac`).catch(() => []);
56	  for (const m of macs) {
57	    const ips: string[] = await ovh(
58	      "GET",
59	      `/dedicated/server/${SERVER}/virtualMac/${m}/virtualAddress`
60	    ).catch(() => []);
61	    if (ips.includes(address)) return m;
62	  }
63	  return null;
64	}
65	
66	/**
67	 * Claim a free IP for a server and create its OVH Virtual MAC so the VM can use it.
68	 * Returns the address + virtualMac + gateway, or null if none available.
69	 */
70	export async function allocateDedicatedIp(
71	  serverId: string,
72	  vmid: number
73	): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
74	  if (!ovhConfigured()) return null;
75	  // Atomically claim a FREE ip
76	  const claim = await db.$transaction(async (tx) => {
77	    const ip = await tx.dedicatedIp.findFirst({ where: { status: "FREE" }, orderBy: { createdAt: "asc" } });
78	    if (!ip) return null;
79	    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
80	    return ip;
81	  });
82	  if (!claim) return null;
83	
84	  try {
85	    // Reuse an existing vMAC for this IP if one is already bound; else create one.
86	    let mac = await findVirtualMacForIp(claim.address);
87	    if (!mac) {
88	      // Creation is asynchronous (returns a task) — kick it off then poll.
89	      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
90	      for (let i = 0; i < 40 && !mac; i++) {
91	        await new Promise((r) => setTimeout(r, 3000));
92	        mac = await findVirtualMacForIp(claim.address);
93	      }
94	    }
95	    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
96	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
97	    return { address: claim.address, virtualMac: mac, gateway: ovhGateway() };
98	  } catch (e) {
99	    // Roll the claim back to FREE on failure
100	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
101	    throw e;
102	  }
103	}
104	
105	/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual MAC). */
106	export async function releaseDedicatedIp(serverId: string): Promise<void> {
107	  const ip = await db.dedicatedIp.findUnique({ where: { serverId } });
108	  if (!ip) return;
109	  if (ovhConfigured() && ip.virtualMac) {
110	    try {
111	      // Remove the IP from the vMAC, then delete the vMAC.
112	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
113	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
114	    } catch {
115	      /* best-effort */
116	    }
117	  }
118	  await db.dedicatedIp.update({
119	    where: { id: ip.id },
120	    data: { status: "FREE", serverId: null, virtualMac: null },
121	  });
122	}
123	
124	/** Set reverse DNS (PTR) for a dedicated IP. */
125	export async function setDedicatedReverse(address: string, reverse: string): Promise<void> {
126	  if (!ovhConfigured()) return;
127	  await ovhApi.setReverse(`${address}/32`, address, reverse);
128	  await db.dedicatedIp.updateMany({ where: { address }, data: { reverse } });
129	}
