24	function generatePassword(): string {
25	  // URL-safe, no ambiguous chars, 16 chars
26	  return randomBytes(24).toString("base64url").replace(/[-_]/g, "x").slice(0, 16);
27	}
28	
29	async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any; node: any }> {
30	  const server = await db.server.findUnique({
31	    where: { id: job.serverId! },
32	    include: { plan: true, osTemplate: true, node: true },
33	  });
34	  if (!server) throw new Error(`Server ${job.serverId} not found`);
35	  return server as any;
36	}
37	
38	/** Resolve the Proxmox client + node config for a server (falls back to the primary node). */
39	async function nodeFor(server: any) {
40	  const n =
41	    server.node ??
42	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
43	    (await db.node.findFirst({ where: { enabled: true } }));
44	  if (!n) {
45	    // No Node rows yet — use the env-configured primary via the global client.
46	    return { conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node, waitForTask, nextVmid, vmStatus: (v: number) => pve.get(`/nodes/${node}/qemu/${v}/status/current`) } as any, row: null };
47	  }
48	  return { conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }), row: n };
49	}
50	
51	/** YAML-safe indent of a multi-line script under a `content: |` block. */
52	function indentBlock(text: string, spaces: number): string {
53	  const pad = " ".repeat(spaces);
54	  return text.split("\n").map((l) => pad + l).join("\n");
55	}
56	
57	/**
58	 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
59	 * plus any control-panel/app install script and selected add-ons. Long installs
60	 * run in the background so the VM reports ready promptly.
61	 */
62	function buildCloudInit(server: any): string {
63	  const addons = (server.addons ?? {}) as { malwareScanner?: boolean; dailyBackup?: boolean; docker?: boolean };
64	  const setup: string[] = [];
65	  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
66	  if (addons.malwareScanner)
67	    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
68	  if (server.osTemplate.setupScript) setup.push(server.osTemplate.setupScript);
69	
70	  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
71	  return `#cloud-config
72	package_update: true
73	packages:
74	  - qemu-guest-agent
75	ssh_pwauth: true
76	disable_root: false
77	write_files:
78	  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
79	    permissions: "0644"
80	    content: |
81	      PermitRootLogin yes
82	      PasswordAuthentication yes
83	  - path: /root/nxeon-setup.sh
84	    permissions: "0755"
85	    content: |
86	${indentBlock(script, 6)}
87	runcmd:
88	  - systemctl enable --now qemu-guest-agent
89	  - systemctl restart ssh || systemctl restart sshd
90	  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
91	`;
92	}
93	
94	const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
95	const SNIPPET_STORAGE = process.env.NXEON_SNIPPET_STORAGE ?? "backup";
96	
97	async function provision(job: Job) {
98	  const server = await loadServer(job);
99	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });
100	
101	  const { conn, row: nodeRow } = await nodeFor(server);
102	  const storage = server.plan.storageTier === "hdd"
103	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
104	    : nodeRow?.storageNvme ?? "vmdata";
105	
106	  const vmid = server.vmid ?? (await conn.nextVmid());
107	  const password = generatePassword();
108	
109	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
110	  // Default: every new server pulls a dedicated IP from the pool; if the pool is
111	  // empty (or OVH isn't configured) it transparently falls back to shared NAT.
112	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
113	  const { getSettingBool: _settingBool } = await import("../lib/settings");
114	  const wantDedicated = server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
115	  if (wantDedicated && ovhConfigured()) {
116	    try {
117	      dedicated = await allocateDedicatedIp(server.id, vmid);
118	    } catch (e) {
119	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
120	    }
121	  }
122	  // Node-aware + transactionally-claimed allocation (passing the server id enables
123	  // the claim path, so two concurrent provisions can't pick the same IP/port).
124	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
125	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));
126	
127	  await db.server.update({
128	    where: { id: server.id },
129	    data: { vmid, ipAddress: ip, sshPort, rootPassword: password },
130	  });
131	
132	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
133	  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
134	  // (worker restart mid-clone, or any transient failure in the steps below) would
135	  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
136	  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
137	  // the clone is idempotent, so skip it when the VM is already present.
138	  let vmAlreadyExists = false;
139	  try {
140	    await conn.vmStatus(vmid);
141	    vmAlreadyExists = true;
142	  } catch {
143	    vmAlreadyExists = false;
144	  }
145	  if (vmAlreadyExists) {
146	    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
147	  } else {
148	    const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
149	      newid: vmid,
150	      name: server.hostname,
151	      full: 1,
152	      storage,
153	    });
154	    await conn.waitForTask(cloneUpid, 600_000);
155	  }
156	
157	  // Per-server cloud-init snippet (base + panel/app install + add-ons)
158	  const snippet = buildCloudInit(server);
159	  await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8").catch((e) =>
160	    console.error("[worker] snippet write failed", e)
161	  );
162	
163	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
164	  const sshkeys = keys.length
165	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
166	    : undefined;
167	  const cfg: Record<string, any> = {
168	    cores: server.plan.cpuCores,
169	    memory: server.plan.ramMB,
170	    ciuser: "root",
171	    cipassword: password,
172	    sshkeys,
173	    nameserver: "1.1.1.1 8.8.8.8",
174	    onboot: 1,
175	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
176	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
177	  };
178	  if (dedicated) {
179	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
180	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
181	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
182	  } else {
183	    // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
184	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`;
185	  }
186	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
187	
188	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
189	    disk: "scsi0",
190	    size: `${server.plan.diskGB}G`,
191	  });
192	
193	  if (!dedicated) await syncPortForwards();
194	
195	  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
196	  await conn.waitForTask(startUpid);
197	
198	  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
199	  const isImage = server.osTemplate.category !== "PLAIN_OS";
200	  const sshLine = dedicated
201	    ? `ssh root@${dedicated.address}`
202	    : `ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`;
203	  await notify(
204	    server.userId,
205	    `Server ${server.hostname} is ready`,
206	    isImage ? `${server.osTemplate.name} is installing in the background (a few minutes). ${sshLine}` : sshLine,
207	    `/dashboard/servers/${server.id}`
208	  );
209	}
210	
211	async function powerAction(job: Job, action: "start" | "stop" | "reboot") {
212	  const server = await loadServer(job);
213	  const { conn } = await nodeFor(server);
214	  const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/${action}`, {});
215	  await conn.waitForTask(upid);
216	  await db.server.update({
217	    where: { id: server.id },
218	    data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
219	  });
220	}
221	
222	async function destroyVm(conn: any, vmid: number) {
223	  // Stop first (ignore failure if already stopped), then destroy
224	  try {
225	    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
226	    await conn.waitForTask(stopUpid);
227	  } catch {
228	    /* already stopped or does not exist */
229	  }
230	  const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${vmid}`, {
231	    "destroy-unreferenced-disks": 1,
232	    purge: 1,
233	  });
234	  await conn.waitForTask(delUpid, 600_000);
235	}
236	
237	async function remove(job: Job) {
238	  const server = await loadServer(job);
239	  const { conn } = await nodeFor(server);
240	  if (server.vmid) {
241	    try {
242	      await destroyVm(conn, server.vmid);
243	    } catch (e: any) {
244	      // VM may never have been created; only swallow "does not exist"
245	      if (!String(e?.body ?? e?.message).includes("does not exist")) throw e;
246	    }
247	    // Best-effort: remove the per-server cloud-init snippet
248	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
249	  }
250	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
251	  await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
252	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
253	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
254	  // diskName and keep billing forever. Remove them and notify the owner. (The
255	  // reinstall guard already blocks the accidental case; a full server delete is an
256	  // intentional teardown, so we drop the volumes with it.)
257	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
258	  if (orphanVolumes.length > 0) {
259	    await db.volume.deleteMany({ where: { serverId: server.id } });
260	    for (const v of orphanVolumes) {
261	      await notify(
262	        v.userId,
263	        `Volume "${v.name}" was removed`,
264	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
265	        "/dashboard/volumes",
266	      ).catch(() => {});
267	    }
268	  }
269	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
270	  // server.delete cascade removes THIS running Job row — the success-path
271	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
272	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
273	  await db.server.delete({ where: { id: server.id } });
274	  await syncPortForwards();
275	}
276	
277	async function reinstall(job: Job) {
278	  const server = await loadServer(job);
279	  const { conn } = await nodeFor(server);
280	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
281	  if (server.vmid) await destroyVm(conn, server.vmid);
282	  await provision(job);
283	}
284	
285	async function suspend(job: Job, unsuspend: boolean) {
286	  const server = await loadServer(job);
287	  const { conn, row: nodeRow } = await nodeFor(server);
288	  if (unsuspend) {
289	    // The dedicated IP was returned to the pool while suspended — re-allocate one
290	    // and reconfigure the public network before starting the VM back up.
291	    if (server.vmid) {
292	      const { getSettingBool: _sb } = await import("../lib/settings");
293	      const wantDedicated = server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
294	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
295	      let reconfigured = alreadyHas ? true : false;
296	      if (wantDedicated && ovhConfigured() && !alreadyHas) {
297	        try {
298	          const d = await allocateDedicatedIp(server.id, server.vmid);
299	          if (d) {
300	            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
301	              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
302	              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
303	            });
304	            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
305	            reconfigured = true;
306	          }
307	        } catch (e) {
308	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; falling back to NAT", e);
309	        }
310	      }
311	      // If we couldn't (or didn't) give it a dedicated IP, its net0 still points at
312	      // the Virtual MAC + failover IP that suspend released back to the pool — that
313	      // IP may now belong to another server. Reconfigure onto shared NAT so it boots
314	      // with a valid, non-conflicting network instead of a dead public config.
315	      if (!reconfigured) {
316	        try {
317	          const ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
318	          const sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
319	          await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
