329	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null } });
330	    await syncPortForwards();
331	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
332	    await conn.waitForTask(upid);
333	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
334	  } else {
335	    try {
336	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
337	      await conn.waitForTask(upid);
