339	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
340	    await syncPortForwards();
341	    // Return the dedicated IP to the pool while the server is suspended, so it
342	    // can be handed to a paying server. Re-allocated on unsuspend.
343	    if (ovhConfigured()) {
