409	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
410	  const server = await loadServer(job);
411	  const payload = (job.payload ?? {}) as { name?: string };
412	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
413	  if (!name) throw new Error("snapshot: invalid name");
414	  const { conn } = await nodeFor(server);
415	  let upid: string;
416	  if (op === "create") {
417	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
418	  } else if (op === "delete") {
419	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
420	  } else {
