512	/**
513	 * Reverse a money side-effect that a job committed up-front but never delivered.
514	 * Server actions charge/credit the wallet before enqueuing the worker job (so the
515	 * UI reflects the change immediately); if the job then fails terminally the money
516	 * must be unwound or the customer is charged for a resize that never happened
517	 * (up) or keeps a downgrade credit for hardware they still have (down).
518	 * Idempotent per job: guarded by the RECONCILED audit marker so a re-run can't
519	 * double-reverse.
520	 */
521	async function reconcileFailedJob(job: Job) {
522	  if (job.type !== "RESIZE") return;
523	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
524	  const cents = p.prorateCents ?? 0;
525	  if (cents <= 0 || !job.serverId) return;
526	
527	  // Idempotency: skip if we already reversed this exact job.
528	  const already = await db.auditLog.findFirst({
529	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
530	  });
531	  if (already) return;
532	
533	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
534	  if (!server) return;
535	
536	  try {
537	    if (p.direction === "up") {
538	      // Upgrade charge never delivered → refund the prorated charge.
539	      await db.$transaction([
540	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
541	        db.walletTransaction.create({
542	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
543	        }),
544	      ]);
545	    } else if (p.direction === "down") {
546	      // Downgrade credit was given but hardware unchanged → claw the credit back.
547	      // Guarded so it can never drive the balance negative; if the customer already
548	      // spent it, we log and leave it (best-effort — they keep a small windfall).
549	      await db.$transaction(async (tx) => {
550	        await debitWallet(tx, server.userId, cents);
551	        await tx.walletTransaction.create({
552	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
553	        });
554	      });
555	    }
556	    await db.auditLog.create({
557	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
558	    });
559	  } catch (e: any) {
560	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
561	    await db.auditLog.create({
562	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
563	    }).catch(() => {});
564	  }
565	}
