567	async function runJob(job: Job) {
568	  // The job is already atomically claimed (status RUNNING, attempts incremented)
569	  // by the loop's compare-and-swap before we get here — see the CAS in main().
570	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
571	  try {
572	    await handlers[job.type](job);
573	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
574	    console.log(`[worker] job ${job.id} DONE`);
575	  } catch (e: any) {
576	    const error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`.slice(0, 2000);
577	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
578	    const current = await db.job.findUnique({ where: { id: job.id } });
579	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
580	    await db.job.update({
581	      where: { id: job.id },
582	      data: { status: retriable ? "QUEUED" : "FAILED", error },
583	    });
584	    if (!retriable) {
585	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
586	      if (job.serverId) {
587	        const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
588	        if (stillExists) {
589	          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
590	        }
591	      }
592	    }
593	  }
594	}
