596	/**
597	 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
598	 * killed worker leaves a job RUNNING forever, which permanently blocks the
599	 * server's "one in-flight job" guard and strands it in a transitional state.
600	 */
601	async function reapStuckJobs() {
602	  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
603	  for (const job of stuck) {
604	    const retriable = job.attempts < MAX_ATTEMPTS;
605	    await db.job.update({
606	      where: { id: job.id },
607	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
608	    });
609	    if (!retriable) {
610	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
611	      if (job.serverId) {
612	        const s = await db.server.findUnique({ where: { id: job.serverId } });
613	        if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
614	          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
615	        }
616	      }
617	    }
618	    console.log(`[worker] reaped stuck job ${job.id} (${job.type}) -> ${retriable ? "QUEUED" : "FAILED"}`);
619	  }
620	}
