677	      try {
678	        await monitorSweep();
679	      } catch (e) {
680	        console.error("[monitor] sweep error", e);
681	      }
682	    }
683	    // Pull newly-delivered OVH IPs into the pool every 5 min
684	    if (ovhConfigured() && Date.now() - lastIpSync > 5 * 60_000) {
685	      lastIpSync = Date.now();
