709	            }
710	          }
711	        }
712	      } catch (e) {
713	        console.error("[worker] IP pool sync error", e);
714	      }
715	    }
716	    try {
717	      const candidate = await db.job.findFirst({
718	        where: { status: "QUEUED" },
719	        orderBy: { createdAt: "asc" },
720	      });
721	      if (candidate) {
722	        // Atomic claim: only the worker whose updateMany matches the still-QUEUED
723	        // row wins. If count===0 another worker (or a retry) already took it, so we
724	        // skip and re-poll — prevents the same job running twice under concurrency.
725	        const claim = await db.job.updateMany({
726	          where: { id: candidate.id, status: "QUEUED" },
727	          data: { status: "RUNNING", attempts: { increment: 1 } },
728	        });
729	        if (claim.count === 1) {
730	          const claimed = await db.job.findUnique({ where: { id: candidate.id } });
731	          if (claimed) await runJob(claimed);
732	        }
733	        // else: lost the race — loop immediately to grab the next queued job.
734	      } else {
735	        await new Promise((r) => setTimeout(r, POLL_MS));
736	      }
737	    } catch (e) {
738	      console.error("[worker] loop error", e);
739	      await new Promise((r) => setTimeout(r, POLL_MS));
740	    }
741	  }
742	}
