24	async function loadVolume(job: Job) {
25	  const payload = (job.payload ?? {}) as { volumeId?: string };
26	  if (!payload.volumeId) throw new Error("volume job: missing volumeId");
27	  const volume = await db.volume.findUnique({
28	    where: { id: payload.volumeId },
29	    include: { server: { include: { node: true } } },
30	  });
31	  if (!volume) throw new Error(`Volume ${payload.volumeId} not found`);
32	  return volume;
33	}
