75	/** First free scsiN slot (scsi0 is the OS disk). Proxmox supports scsi0..scsi30. */
76	function freeScsiSlot(config: Record<string, any>): string {
77	  for (let i = 1; i <= 30; i++) {
78	    if (config[`scsi${i}`] === undefined) return `scsi${i}`;
79	  }
80	  throw new Error("no free scsi slot available on this VM");
81	}
82	
83	/** Find the config key (scsiN / unusedN / …) that currently references `volid`. */
84	function keyForVolid(config: Record<string, any>, volid: string): string | null {
85	  for (const [k, v] of Object.entries(config)) {
86	    if (typeof v === "string" && volidOf(v) === volid) return k;
87	  }
88	  return null;
89	}
90	
91	/**
92	 * VOLUME_CREATE — logical registration only. No physical disk is created until
93	 * the volume is first attached (a Proxmox disk must live on a VM). Flip the row
94	 * from PENDING to DETACHED so the customer can attach it.
95	 */
96	export async function volumeCreate(job: Job): Promise<void> {
97	  const volume = await loadVolume(job);
98	  if (volume.status === "PENDING") {
99	    await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
100	  }
101	  await notify(
102	    volume.userId,
103	    `Volume "${volume.name}" is ready`,
104	    `${volume.sizeGB} GB block storage is available to attach to a server.`,
105	    "/dashboard/volumes"
106	  );
107	}
108	
109	/**
110	 * VOLUME_ATTACH — attach the disk to the target server's VM at a free scsi slot.
111	 * Creates the underlying disk on first attach ("<storage>:<sizeGB>"); on a
112	 * re-attach it re-uses the existing volume id so data is preserved.
113	 */
114	export async function volumeAttach(job: Job): Promise<void> {
115	  const volume = await loadVolume(job);
116	  const server = volume.server;
117	  if (!server || !server.vmid) throw new Error("volume attach: server has no VM");
118	
119	  const { conn, row } = await nodeFor(server);
120	  const storage = row?.storageNvme ?? "vmdata";
121	
122	  const config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
123	  const slot = freeScsiSlot(config);
124	
125	  // Re-use the existing disk (by volid) if this volume was attached before;
126	  // otherwise let Proxmox create a fresh <storage>:<sizeGB> disk.
127	  const source = volume.diskName ? volume.diskName : `${storage}:${volume.sizeGB}`;
128	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { [slot]: source });
129	
130	  // Read back the real volume id Proxmox assigned/kept at the slot.
131	  const after = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
132	  const volid = volidOf(after[slot]) || volume.diskName || null;
133	
134	  await db.volume.update({
135	    where: { id: volume.id },
136	    data: { status: "ATTACHED", serverId: server.id, diskName: volid },
137	  });
138	  await notify(
139	    volume.userId,
140	    `Volume "${volume.name}" attached to ${server.hostname}`,
141	    `${volume.sizeGB} GB is now available as ${slot}. Format and mount it inside the server to use it.`,
142	    `/dashboard/servers/${server.id}`
143	  );
144	}
145	
146	/**
147	 * VOLUME_DETACH — detach the disk from the VM (Proxmox moves it to an "unused"
148	 * entry, preserving the data). The volume stays pinned to this server so it can
149	 * be re-attached here later.
150	 */
151	export async function volumeDetach(job: Job): Promise<void> {
152	  const volume = await loadVolume(job);
153	  const server = volume.server;
154	
155	  if (server?.vmid && volume.diskName) {
156	    const { conn } = await nodeFor(server);
157	    const config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
158	    const key = keyForVolid(config, volume.diskName);
159	    if (key && key.startsWith("scsi")) {
160	      await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
161	    }
162	  }
163	
164	  await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
165	  if (server) {
166	    await notify(
167	      volume.userId,
168	      `Volume "${volume.name}" detached from ${server.hostname}`,
169	      "The volume and its data are preserved and can be re-attached to the same server.",
170	      "/dashboard/volumes"
171	    );
172	  }
173	}
174	
175	/**
176	 * VOLUME_DELETE — detach (if attached) then permanently destroy the underlying
177	 * disk, and remove the Volume row.
178	 */
179	export async function volumeDelete(job: Job): Promise<void> {
180	  const volume = await loadVolume(job);
181	  const server = volume.server;
182	
183	  if (server?.vmid && volume.diskName) {
184	    const { conn } = await nodeFor(server);
185	    try {
186	      let config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
187	      let key = keyForVolid(config, volume.diskName);
188	
189	      // If still mounted, detach to an "unused" entry first.
190	      if (key && key.startsWith("scsi")) {
191	        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
192	        config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
193	        key = keyForVolid(config, volume.diskName);
194	      }
195	      // Deleting an "unused" entry destroys the underlying disk.
196	      if (key) {
197	        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
198	      }
199	    } catch (e: any) {
200	      const msg = String(e?.body ?? e?.message ?? e);
201	      if (!msg.includes("does not exist")) throw e;
202	    }
203	  }
204	
205	  await db.volume.delete({ where: { id: volume.id } });
206	  await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
207	}
