16	/**
17	 * Monitoring sweep — run periodically from the worker loop. Read-only checks
18	 * that raise dashboard notifications for all ADMINs when a threshold trips.
19	 *
20	 * Notifications are de-duplicated by title within a rolling window so a
21	 * persistent condition (e.g. a node stuck at 90% disk) alerts once every few
22	 * hours rather than every sweep.
23	 */
24	
25	const DEDUPE_HOURS = Number(process.env.NXEON_ALERT_DEDUPE_HOURS ?? 3);
26	
27	/**
28	 * Fan a single alert out to every ADMIN, unless an identically-titled alert
29	 * already went out within the dedupe window.
30	 */
31	async function notifyAdmins(
32	  title: string,
33	  body: string,
34	  href = "/admin/monitoring"
35	): Promise<void> {
36	  const since = new Date(Date.now() - DEDUPE_HOURS * 60 * 60_000);
37	  const recent = await db.notification.findFirst({
38	    where: { title, createdAt: { gt: since } },
39	    select: { id: true },
40	  });
41	  if (recent) return;
42	
43	  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
44	  if (admins.length === 0) return;
45	
46	  await db.notification.createMany({
47	    data: admins.map((a) => ({ userId: a.id, title, body, href })),
48	  });
49	}
