51	export async function monitorSweep(): Promise<void> {
52	  // 1. Node disk usage > threshold
53	  try {
54	    const storage = await nodeStorageUsage();
55	    for (const s of storage) {
56	      if (s.reachable && s.total > 0 && s.ratio > DISK_WARN_RATIO) {
57	        const pct = Math.round(s.ratio * 100);
58	        await notifyAdmins(
59	          `Disk capacity warning — ${s.node}/${s.storage} at ${pct}%`,
60	          `Storage "${s.storage}" on node ${s.node} is ${pct}% full ` +
61	            `(${(s.avail / 1024 ** 3).toFixed(0)} GB free). Free space or add capacity to keep provisioning healthy.`
62	        );
63	      }
64	    }
65	  } catch (e) {
66	    console.error("[monitor] disk check error", e);
67	  }
68	
69	  // 2. Node RAM pressure > threshold
70	  try {
71	    const ram = await nodeRamUsage();
72	    for (const r of ram) {
73	      if (r.reachable && r.total > 0 && r.ratio > RAM_WARN_RATIO) {
74	        const pct = Math.round(r.ratio * 100);
75	        await notifyAdmins(
76	          `Memory pressure — ${r.node} at ${pct}%`,
77	          `Node ${r.node} RAM is ${pct}% used. New deploys may be refused until usage drops.`
78	        );
79	      }
80	    }
81	  } catch (e) {
82	    console.error("[monitor] ram check error", e);
83	  }
84	
85	  // 3. Stuck jobs (RUNNING beyond the stuck threshold)
86	  try {
87	    const stuck = await stuckJobs();
88	    if (stuck.length > 0) {
89	      const mins = Math.round(STUCK_JOB_MS / 60_000);
90	      const lines = stuck
91	        .slice(0, 8)
92	        .map(
93	          (j) =>
94	            `• ${j.type}${j.hostname ? ` (${j.hostname})` : ""} — running ${fmtAge(
95	              Date.now() - j.updatedAt.getTime()
96	            )}`
97	        )
98	        .join("\n");
99	      await notifyAdmins(
100	        `Stuck jobs — ${stuck.length} running > ${mins}m`,
101	        `The worker has job(s) stuck in RUNNING:\n${lines}`
102	      );
103	    }
104	  } catch (e) {
105	    console.error("[monitor] stuck-job check error", e);
106	  }
107	
108	  // 4. Worker liveness + pending-job backlog
109	  try {
110	    const wh = await workerHealth();
111	    if (wh.status === "down") {
112	      await notifyAdmins(
113	        "Worker appears stopped",
114	        wh.detail + ". Check the provisioning worker process."
115	      );
116	    }
117	    if (wh.queuedBacklog >= QUEUE_BACKLOG_ALERT) {
118	      await notifyAdmins(
119	        `Job backlog building — ${wh.queuedBacklog} queued`,
120	        `${wh.queuedBacklog} jobs are waiting in the queue. The worker may be overloaded or slow.`
121	      );
122	    }
123	  } catch (e) {
124	    console.error("[monitor] worker check error", e);
125	  }
126	
127	  // 5. Backup freshness (best-effort; skipped if backup storage isn't listable)
128	  try {
129	    const bk = await backupSummary();
130	    if (bk.reachable && bk.count > 0 && bk.newestCtime !== null) {
131	      const ageMs = Date.now() - bk.newestCtime * 1000;
132	      if (ageMs > BACKUP_STALE_MS) {
133	        await notifyAdmins(
134	          `Backups look stale — newest is ${fmtAge(ageMs)} old`,
135	          `The most recent backup on disk is ${fmtAge(ageMs)} old. Verify the backup schedule is running.`
136	        );
137	      }
138	    }
139	  } catch (e) {
140	    console.error("[monitor] backup check error", e);
141	  }
142	}
