3	/**
4	 * Scheduled-backup sweep.
5	 *
6	 * `scheduledBackupSweep` finds RUNNING servers that opted into recurring backups
7	 * (`autoBackup=true`) whose last automatic backup is older than their configured
8	 * cadence (or which have never had one), and enqueues a BACKUP_CREATE job for
9	 * each — de-duping on any in-flight job so it's safe to call on a timer.
10	 *
11	 * NOTE: `worker/index.ts` owns the job loop; it already knows how to run
12	 * BACKUP_CREATE jobs. Wire this sweep into the main loop on a timer, e.g.:
13	 *
14	 *   import { scheduledBackupSweep } from "./backup-schedule";
15	 *   if (Date.now() - lastBackupSweep > 15 * 60_000) {
16	 *     lastBackupSweep = Date.now();
17	 *     try { await scheduledBackupSweep(); } catch (e) { console.error(e); }
18	 *   }
19	 */
20	export async function scheduledBackupSweep(): Promise<void> {
21	  const now = Date.now();
22	
23	  const candidates = await db.server.findMany({
24	    where: {
25	      status: "RUNNING",
26	      autoBackup: true,
27	      backupIntervalHours: { not: null },
28	    },
29	    select: {
30	      id: true,
31	      hostname: true,
32	      backupIntervalHours: true,
33	      lastAutoBackup: true,
34	    },
35	  });
36	  if (candidates.length === 0) return;
37	
38	  let enqueued = 0;
39	  for (const s of candidates) {
40	    const intervalMs = (s.backupIntervalHours ?? 0) * 60 * 60_000;
41	    if (intervalMs <= 0) continue;
42	
43	    // Due if it has never run, or the cadence has elapsed since the last one.
44	    const dueAt = s.lastAutoBackup ? s.lastAutoBackup.getTime() + intervalMs : 0;
45	    if (now < dueAt) continue;
46	
47	    // Respect the one-in-flight-job-per-server invariant.
48	    const inflight = await db.job.count({
49	      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
50	    });
51	    if (inflight > 0) continue;
52	
53	    await db.job.create({ data: { type: "BACKUP_CREATE", serverId: s.id } });
54	    // Mark the schedule as satisfied now so a slow backup / a second sweep pass
55	    // doesn't pile up duplicate jobs; the timestamp anchors the next window.
56	    await db.server.update({
57	      where: { id: s.id },
58	      data: { lastAutoBackup: new Date() },
59	    });
60	    enqueued++;
61	  }
62	
63	  if (enqueued > 0) console.log(`[backup-schedule] sweep enqueued ${enqueued} backup job(s)`);
64	}
