1	import { db } from "../lib/db";
2	import { GAME_FAMILIES, type GameFamily } from "../lib/games";
3	import { execFile } from "node:child_process";
4	import { promisify } from "node:util";
5	import type { Job } from "@prisma/client";
6	
7	const execFileP = promisify(execFile);
8	
9	/**
10	 * Game-server auto-update handlers.
11	 *
12	 * `gameUpdate` runs a best-effort, per-family update command over SSH against
13	 * the server's private IP (the worker can reach vmbr1). `gameUpdateSweep` finds
14	 * RUNNING game servers with `autoUpdate=true` and enqueues GAME_UPDATE jobs for
15	 * them — safe to call periodically (it de-dupes on in-flight jobs).
16	 *
17	 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire these
18	 * in there (`GAME_UPDATE: gameUpdate`) and call `gameUpdateSweep()` on a timer.
19	 */
20	
21	/** Steam dedicated-server app IDs for steamcmd-based families. */
22	const STEAM_APPID: Partial<Record<GameFamily, string>> = {
23	  valheim: "896660",
24	  rust: "258550",
25	  palworld: "2394010",
26	  cs2: "730",
27	};
28	
29	/** systemd service name candidates per family (first that exists wins). */
30	const SERVICE_HINT: Record<GameFamily, string> = {
31	  minecraft: "minecraft",
32	  valheim: "valheim",
33	  rust: "rust",
34	  palworld: "palworld",
35	  cs2: "cs2",
36	  terraria: "terraria",
37	};
38	
39	/**
40	 * Build a best-effort remote update command. For steamcmd-based games we run an
41	 * anonymous `app_update ... validate` if steamcmd is present, then (always)
42	 * restart the matching systemd service. Everything is tolerant (`|| true`) so a
43	 * missing tool/service never fails the whole job for an otherwise-healthy VM.
44	 */
45	function updateCommand(family: GameFamily): string {
46	  const appId = STEAM_APPID[family];
47	  const svc = SERVICE_HINT[family];
48	  const steam = appId
49	    ? `if command -v steamcmd >/dev/null 2>&1; then steamcmd +login anonymous +app_update ${appId} validate +quit || true; fi; `
50	    : "";
51	  // Restart the named service, then a "<family>-server" variant, then any unit
52	  // whose name contains the family; never hard-fail.
53	  const restart =
54	    `systemctl restart ${svc} 2>/dev/null || ` +
55	    `systemctl restart ${svc}-server 2>/dev/null || ` +
56	    `svc=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${family} | head -1 | awk '{print $1}'); ` +
57	    `if [ -n "$svc" ]; then systemctl restart "$svc" || true; fi`;
58	  return `set -e; ${steam}${restart}; true`;
59	}
60	
61	async function loadGameServer(serverId: string) {
62	  const server = await db.server.findUnique({
63	    where: { id: serverId },
64	    include: { osTemplate: true },
65	  });
66	  if (!server) throw new Error(`Server ${serverId} not found`);
67	  return server;
68	}
