78	/** Run the per-family update command over SSH (sshpass + private IP). */
79	export async function gameUpdate(job: Job): Promise<void> {
80	  const server = await loadGameServer(job.serverId!);
81	  const family = server.osTemplate.family as GameFamily;
82	  if (!GAME_FAMILIES.includes(family)) {
83	    throw new Error(`game update: ${server.hostname} is not a game server`);
84	  }
85	  if (server.status !== "RUNNING") throw new Error("game update: server is not running");
86	  if (!server.ipAddress || !server.rootPassword) {
87	    throw new Error("game update: server has no IP/password yet");
88	  }
89	
90	  const remote = updateCommand(family);
91	  await execFileP(
92	    "sshpass",
93	    [
94	      "-p",
95	      server.rootPassword,
96	      "ssh",
97	      "-o",
98	      "StrictHostKeyChecking=no",
99	      "-o",
100	      "UserKnownHostsFile=/dev/null",
101	      "-o",
102	      "ConnectTimeout=15",
103	      `root@${server.ipAddress}`,
104	      remote,
105	    ],
106	    { timeout: 600_000, maxBuffer: 4 * 1024 * 1024 }
107	  );
108	
109	  await notify(
110	    server.userId,
111	    `${server.osTemplate.name} updated on ${server.hostname}`,
112	    "The latest server update was applied and the service was restarted.",
113	    `/dashboard/servers/${server.id}`
114	  );
115	}
