117	/**
118	 * Enqueue GAME_UPDATE jobs for every RUNNING game server that has opted into
119	 * auto-update and has no job already in flight. Idempotent / safe to call on a
120	 * timer. Returns nothing; logs a summary.
121	 */
122	export async function gameUpdateSweep(): Promise<void> {
123	  const candidates = await db.server.findMany({
124	    where: {
125	      status: "RUNNING",
126	      autoUpdate: true,
127	      osTemplate: { family: { in: [...GAME_FAMILIES] } },
128	    },
129	    select: { id: true, hostname: true },
130	  });
131	  if (candidates.length === 0) return;
132	
133	  let enqueued = 0;
134	  for (const s of candidates) {
135	    const inflight = await db.job.count({
136	      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
137	    });
138	    if (inflight > 0) continue;
139	    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
140	    enqueued++;
141	  }
142	  if (enqueued > 0) console.log(`[game-update] sweep enqueued ${enqueued} update job(s)`);
143	}
