5	/**
6	 * Self-service backup restore handler.
7	 *
8	 * Restores a selected vzdump archive back onto the server's existing VM via the
9	 * Proxmox API: stop -> restore (force overwrite) -> start. Ownership and archive
10	 * validation are enforced at enqueue time (`lib/actions-server-ops.ts`), so this
11	 * handler trusts the `volid` in the job payload.
12	 *
13	 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire this in
14	 * there as `BACKUP_RESTORE: backupRestore`.
15	 */
16	
17	async function loadServer(serverId: string) {
