26	/** Resolve a Proxmox client for the server's node (mirrors worker/index.ts). */
27	async function nodeFor(server: any) {
28	  const n =
29	    server.node ??
30	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
31	    (await db.node.findFirst({ where: { enabled: true } }));
32	  if (!n) {
33	    return {
34	      get: pve.get,
35	      post: pve.post,
36	      put: pve.put,
37	      del: pve.del,
38	      node: envNode,
39	      waitForTask,
40	      nextVmid,
41	      vmStatus: (v: number) => pve.get(`/nodes/${envNode}/qemu/${v}/status/current`),
42	    } as any;
43	  }
44	  return pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret });
45	}
