1	// "Build with Claude AI" worker handler — SAFE, plan-then-approve.
2	//
3	// Two phases, driven by ClaudeBuild.approved:
4	//   1. PLAN  (approved=false): ask Claude — with the OWNER'S effective key — for
5	//      an ordered JSON array of non-destructive shell commands. Store it to
6	//      ClaudeBuild.plan and set AWAITING_APPROVAL. NOTHING is executed.
7	//   2. EXECUTE (approved=true): run each approved command over SSH, enforcing a
8	//      denylist, a per-command timeout, and a hard command cap. Append output to
9	//      ClaudeBuild.log, then set DONE (or FAILED on error). Never runs a command
10	//      that was not part of the approved plan.
11	//
12	// This handler is wired into worker/index.ts's `handlers` map by the
13	// orchestrator (see INTEGRATION NEEDED in the final report):
14	//   import { claudeBuild } from "./claude";
15	//   CLAUDE_BUILD: claudeBuild,
16	
17	import { execFile } from "node:child_process";
18	import { promisify } from "node:util";
19	import { db } from "../lib/db";
20	import { askClaude, effectiveKeyFor, type ClaudeMessage } from "../lib/anthropic";
21	import type { Job } from "@prisma/client";
22	
23	const execFileAsync = promisify(execFile);
24	
25	/** Hard cap on the number of commands executed for a single build. */
26	export const CLAUDE_MAX_COMMANDS = 20;
27	
28	/** Per-command SSH execution timeout. */
29	const CMD_TIMEOUT_MS = 120_000;
30	/** Cap on captured output per command (chars) to keep the log bounded. */
31	const MAX_OUTPUT_CHARS = 4000;
32	/** Cap on total stored log size. */
33	const MAX_LOG_CHARS = 60_000;
34	
35	type PlanStep = { cmd: string; intent: string };
36	
37	const PLAN_SYSTEM_PROMPT = `You are an expert Linux server administrator. You are given a goal for a SINGLE Debian/Ubuntu server that you operate on over SSH as root. Produce a PLAN — do NOT run anything.
38	
39	Output ONLY a JSON array of steps and NOTHING else (no markdown, no backticks, no prose before or after). Each step is an object:
40	{"cmd": "<one non-interactive shell command>", "intent": "<short plain-English explanation of what it does and why>"}
41	
42	Rules for the plan:
43	- Operate ONLY on this one server. Never touch other hosts, networks, or cloud APIs.
44	- Commands must be non-interactive: use flags like -y and DEBIAN_FRONTEND=noninteractive; never launch editors, pagers, REPLs, or anything that waits for input.
45	- NON-DESTRUCTIVE ONLY. Absolutely no whole-disk or whole-system operations: no rm -rf /, no mkfs/fdisk/dd on disks, no wiping /etc, no reboot/shutdown/poweroff/halt, no user/password changes, no disabling SSH.
46	- Keep each command self-contained and idempotent where possible.
47	- Prefer standard packages and services (apt, systemctl, nginx, ufw, etc.).
48	- At most ${CLAUDE_MAX_COMMANDS} steps. If the goal cannot be met safely, return an empty array [].`;
49	
50	/** Escape a string for safe single-quoted inclusion in a bash -c argument. */
51	function shSingleQuote(s: string): string {
52	  return `'${s.replace(/'/g, `'\\''`)}'`;
53	}
54	
55	/** Reject catastrophic commands as a defense-in-depth backstop (denylist). */
56	function isForbidden(cmd: string): boolean {
57	  const c = cmd.toLowerCase();
58	  const patterns = [
59	    /rm\s+(-[a-z]*\s+)*(-[a-z]*r[a-z]*f|-[a-z]*f[a-z]*r)\s+\/(\s|$)/, // rm -rf /
60	    /\bmkfs\b/,
61	    /\bfdisk\b/,
62	    /\bparted\b/,
63	    /\bdd\b[^|]*of=\/dev\//, // dd of=/dev/*
64	    /\b(reboot|shutdown|poweroff|halt|init\s+0|init\s+6)\b/,
65	    /\bshred\b/,
66	    /\bpasswd\b/,
67	    /:\(\)\s*\{.*\};:/, // fork bomb :(){ :|:& };:
68	    />\s*\/dev\/sd[a-z]/,
69	    /\bsystemctl\s+(stop|disable|mask)\s+(ssh|sshd)\b/,
70	  ];
71	  return patterns.some((p) => p.test(c));
72	}
73	
74	/** Run one command on the server over SSH via sshpass. Never throws. */
75	async function sshExec(
76	  server: { ipAddress: string | null; rootPassword: string | null },
77	  command: string
78	): Promise<{ output: string; failed: boolean }> {
79	  if (!server.ipAddress || !server.rootPassword) {
80	    return { output: "[nxeon] server has no reachable IP or root password", failed: true };
81	  }
82	  // The worker reaches VMs directly on the private bridge (10.20.0.0/24), so we
83	  // connect to the private IP on port 22.
84	  const args = [
85	    "-p",
86	    server.rootPassword,
87	    "ssh",
88	    "-o",
89	    "StrictHostKeyChecking=no",
90	    "-o",
91	    "UserKnownHostsFile=/dev/null",
92	    "-o",
93	    "ConnectTimeout=10",
94	    "-o",
95	    "BatchMode=no",
96	    `root@${server.ipAddress}`,
97	    // Wrap in bash -c with a single-quoted payload so complex commands survive intact.
98	    `bash -c ${shSingleQuote(command)}`,
99	  ];
100	  try {
101	    const { stdout, stderr } = await execFileAsync("sshpass", args, {
102	      timeout: CMD_TIMEOUT_MS,
103	      maxBuffer: 8 * 1024 * 1024,
104	      env: { ...process.env, DEBIAN_FRONTEND: "noninteractive" },
105	    });
106	    const out = `${stdout}${stderr ? `\n${stderr}` : ""}`.trim();
107	    return { output: out || "[no output]", failed: false };
108	  } catch (e: any) {
109	    // execFile rejects on non-zero exit or timeout; capture whatever we got.
110	    const out = `${e?.stdout ?? ""}${e?.stderr ? `\n${e.stderr}` : ""}`.trim();
111	    const reason = e?.killed
112	      ? `[nxeon] command timed out after ${CMD_TIMEOUT_MS / 1000}s`
113	      : `[nxeon] command exited with code ${e?.code ?? "?"}`;
114	    return { output: `${out ? out + "\n" : ""}${reason}`, failed: true };
115	  }
116	}
117	
118	function truncate(s: string, max: number): string {
119	  return s.length > max ? s.slice(0, max) + "\n…[truncated]" : s;
120	}
121	
122	/** Parse Claude's plan reply into a validated list of steps, or null. */
123	function parsePlan(reply: string): PlanStep[] | null {
124	  const start = reply.indexOf("[");
125	  const end = reply.lastIndexOf("]");
126	  if (start === -1 || end === -1 || end < start) return null;
127	  let raw: unknown;
128	  try {
129	    raw = JSON.parse(reply.slice(start, end + 1));
130	  } catch {
131	    return null;
132	  }
133	  if (!Array.isArray(raw)) return null;
134	  const steps: PlanStep[] = [];
135	  for (const item of raw) {
136	    if (typeof item === "string") {
137	      const cmd = item.trim();
138	      if (cmd) steps.push({ cmd, intent: "" });
139	    } else if (item && typeof item === "object") {
140	      const anyItem = item as Record<string, unknown>;
141	      const cmd = String(anyItem.cmd ?? anyItem.command ?? "").trim();
142	      const intent = String(anyItem.intent ?? anyItem.description ?? "").trim();
143	      if (cmd) steps.push({ cmd, intent });
144	    }
145	  }
146	  return steps.length ? steps : null;
147	}
148	
149	async function failBuild(buildId: string, priorLog: string, note: string): Promise<void> {
150	  await db.claudeBuild.update({
151	    where: { id: buildId },
152	    data: { status: "FAILED", log: truncate(priorLog + `\n[nxeon] ${note}\n`, MAX_LOG_CHARS) },
153	  });
154	}
155	
156	export async function claudeBuild(job: Job): Promise<void> {
157	  const payload = (job.payload ?? {}) as { buildId?: string };
158	  const buildId = payload.buildId;
159	  if (!buildId) throw new Error("claudeBuild: missing buildId in job payload");
160	
161	  const build = await db.claudeBuild.findUnique({ where: { id: buildId }, include: { server: true } });
162	  if (!build) throw new Error(`claudeBuild: build ${buildId} not found`);
163	  const server = build.server;
164	
165	  // Terminal builds are never re-processed by a stray/duplicate job.
166	  if (build.status === "DONE" || build.status === "FAILED") return;
167	
168	  // Everything is gated on an effective owner key + a reachable RUNNING server.
169	  const owner = await db.user.findUnique({
170	    where: { id: build.userId },
171	    select: { anthropicKeyEnc: true },
172	  });
173	  const apiKey = effectiveKeyFor(owner);
174	  if (!apiKey) {
175	    await failBuild(buildId, build.log ?? "", "No Anthropic API key available for the owner.");
176	    return;
177	  }
178	  if (!server || server.status !== "RUNNING") {
179	    await failBuild(buildId, build.log ?? "", "The server is not running.");
180	    return;
181	  }
182	  if (!server.ipAddress || !server.rootPassword) {
183	    await failBuild(buildId, build.log ?? "", "The server is not reachable (no IP or root password).");
184	    return;
185	  }
186	
187	  if (!build.approved) {
188	    await planPhase(buildId, build.status, build.prompt, build.log ?? "", apiKey);
189	  } else {
190	    await executePhase(buildId, build.prompt, build.plan, build.log ?? "", server);
191	  }
192	}
