194	/** Phase 1: ask Claude for a plan, store it, and await owner approval. */
195	async function planPhase(
196	  buildId: string,
197	  status: string,
198	  prompt: string,
199	  priorLog: string,
200	  apiKey: string
201	): Promise<void> {
202	  // Only plan for a not-yet-planned build; ignore duplicate jobs otherwise.
203	  if (status !== "QUEUED" && status !== "PLANNING") return;
204	
205	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: "PLANNING" } });
206	
207	  const messages: ClaudeMessage[] = [
208	    { role: "user", content: `Goal: ${prompt}\n\nProduce the plan now as a JSON array of {"cmd","intent"} steps.` },
209	  ];
210	
211	  let reply: string;
212	  try {
213	    reply = await askClaude(apiKey, messages, PLAN_SYSTEM_PROMPT, { maxTokens: 4096, timeoutMs: 90_000 });
214	  } catch (e: any) {
215	    await failBuild(buildId, priorLog, `Planning failed: ${e?.message ?? e}`);
216	    return;
217	  }
218	
219	  const plan = parsePlan(reply);
220	  if (!plan) {
221	    await failBuild(buildId, priorLog, "Claude did not return a usable plan for this goal.");
222	    return;
223	  }
224	
225	  const capped = plan.slice(0, CLAUDE_MAX_COMMANDS);
226	  await db.claudeBuild.update({
227	    where: { id: buildId },
228	    data: { status: "AWAITING_APPROVAL", plan: JSON.stringify(capped) },
229	  });
230	}
231	
232	/** Phase 2: execute the OWNER-APPROVED plan over SSH. */
233	async function executePhase(
234	  buildId: string,
235	  prompt: string,
236	  planJson: string | null,
237	  priorLog: string,
238	  server: { ipAddress: string | null; rootPassword: string | null; hostname: string | null }
239	): Promise<void> {
240	  let plan: PlanStep[] = [];
241	  try {
242	    const parsed = JSON.parse(planJson ?? "[]");
243	    if (Array.isArray(parsed)) {
244	      plan = parsed
245	        .map((s: any) => ({ cmd: String(s?.cmd ?? s ?? "").trim(), intent: String(s?.intent ?? "") }))
246	        .filter((s: PlanStep) => s.cmd);
247	    }
248	  } catch {
249	    plan = [];
250	  }
251	
252	  if (plan.length === 0) {
253	    await failBuild(buildId, priorLog, "No approved plan to execute.");
254	    return;
255	  }
256	
257	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: "RUNNING" } });
258	
259	  const commands = plan.slice(0, CLAUDE_MAX_COMMANDS);
260	  let log = priorLog;
261	  const append = async (chunk: string, steps: number) => {
262	    log = truncate(log + chunk, MAX_LOG_CHARS);
263	    await db.claudeBuild.update({ where: { id: buildId }, data: { log, steps } });
264	  };
265	
266	  await append(`# Goal: ${prompt}\n# Executing approved plan (${commands.length} command(s))\n\n`, 0);
267	
268	  let steps = 0;
269	  let finalStatus: "DONE" | "FAILED" = "DONE";
270	
271	  try {
272	    for (const step of commands) {
273	      const command = step.cmd;
274	
275	      // Defense-in-depth: even an approved plan is re-checked against the denylist.
276	      if (isForbidden(command)) {
277	        await append(`\n$ ${command}\n[nxeon] Skipped — blocked by the safety denylist.\n`, steps);
278	        continue;
279	      }
280	
281	      steps += 1;
282	      const { output, failed } = await sshExec(server, command);
283	      const shown = truncate(output, MAX_OUTPUT_CHARS);
284	      await append(`\n$ ${command}\n${shown}\n`, steps);
285	
286	      if (failed) {
287	        await append(`\n[nxeon] Command failed — stopping execution.\n`, steps);
288	        finalStatus = "FAILED";
289	        break;
290	      }
291	    }
292	  } catch (e: any) {
293	    await append(`\n[nxeon] Build error: ${e?.message ?? e}\n`, steps);
294	    finalStatus = "FAILED";
295	  }
296	
297	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: finalStatus, steps } });
298	
299	  try {
300	    await db.notification.create({
301	      data: {
302	        userId: (await db.claudeBuild.findUnique({ where: { id: buildId }, select: { userId: true } }))!.userId,
303	        title:
304	          finalStatus === "DONE"
305	            ? `Claude finished building on ${server.hostname}`
306	            : `Claude build failed on ${server.hostname}`,
307	        body: prompt.slice(0, 140),
308	        href: `/dashboard/build`,
309	      },
310	    });
311	  } catch {
312	    /* notification is best-effort */
313	  }
314	}
