1	import { db } from "../lib/db";
2	
3	/**
4	 * Best-effort geo-enrichment of captured visits. Called periodically from the
5	 * worker loop. For each recent visit still marked `geocoded=false` we resolve
6	 * its IP to a coarse location — first from the local `GeoCache`, else via the
7	 * free, keyless ip-api.com endpoint — then copy the location onto the visit and
8	 * flip `geocoded=true`.
9	 *
10	 * Design constraints:
11	 *  - No API key, so we respect ip-api's free tier (~45 req/min) by capping the
12	 *    number of *external* lookups per sweep and pacing them.
13	 *  - Private / non-routable IPs are skipped (marked geocoded with no location).
14	 *  - Every network/DB op is defensive: one failure never aborts the sweep.
15	 */
16	
17	const MAX_EXTERNAL_PER_SWEEP = 40; // stay under ip-api's 45/min free limit
18	const PACE_MS = 1500; // spacing between external calls
19	const BATCH = 200; // how many pending visits to consider per sweep
20	
21	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
22	
23	type Geo = {
24	  country: string | null;
25	  region: string | null;
26	  city: string | null;
27	  lat: number | null;
28	  lng: number | null;
29	};
30	
31	const EMPTY: Geo = { country: null, region: null, city: null, lat: null, lng: null };
32	
33	/** True for private, loopback, link-local or otherwise non-geolocatable addresses. */
34	function isPrivateIp(ip: string): boolean {
35	  if (!ip || ip === "unknown") return true;
36	  if (ip === "::1" || ip === "127.0.0.1" || ip.startsWith("127.")) return true;
37	  if (ip.startsWith("10.")) return true;
38	  if (ip.startsWith("192.168.")) return true;
39	  if (ip.startsWith("169.254.")) return true; // link-local
40	  // 172.16.0.0 – 172.31.255.255
41	  const m = ip.match(/^172\.(\d+)\./);
42	  if (m) {
43	    const second = Number(m[1]);
44	    if (second >= 16 && second <= 31) return true;
45	  }
46	  // IPv6 unique-local / link-local
47	  const low = ip.toLowerCase();
48	  if (low.startsWith("fc") || low.startsWith("fd") || low.startsWith("fe80")) return true;
49	  return false;
50	}
51	
52	/** Look up an IP via ip-api.com. Returns null on any failure. */
53	async function fetchGeo(ip: string): Promise<Geo | null> {
54	  try {
55	    const res = await fetch(
56	      `http://ip-api.com/json/${encodeURIComponent(ip)}?fields=status,country,regionName,city,lat,lon`,
57	      { signal: AbortSignal.timeout(6000) }
58	    );
59	    if (!res.ok) return null;
60	    const data = (await res.json()) as {
61	      status?: string;
62	      country?: string;
63	      regionName?: string;
64	      city?: string;
65	      lat?: number;
66	      lon?: number;
67	    };
68	    if (data.status !== "success") return null;
69	    return {
70	      country: data.country ?? null,
71	      region: data.regionName ?? null,
72	      city: data.city ?? null,
73	      lat: typeof data.lat === "number" ? data.lat : null,
74	      lng: typeof data.lon === "number" ? data.lon : null,
75	    };
76	  } catch {
77	    return null;
78	  }
79	}
80	
81	export async function geoEnrichSweep(): Promise<{ processed: number; external: number }> {
82	  let processed = 0;
83	  let external = 0;
84	
85	  let pending: { id: string; ip: string }[] = [];
86	  try {
87	    pending = await db.visit.findMany({
88	      where: { geocoded: false },
89	      orderBy: { createdAt: "desc" },
90	      take: BATCH,
91	      select: { id: true, ip: true },
92	    });
93	  } catch (e) {
94	    console.error("[geo] failed to load pending visits", e);
95	    return { processed, external };
96	  }
97	
98	  // Resolve one IP at a time, sharing results across visits from the same IP
99	  // within this sweep so a burst from one client costs a single lookup.
100	  const resolved = new Map<string, Geo>();
101	
102	  for (const visit of pending) {
103	    try {
104	      const ip = visit.ip;
105	      let geo = resolved.get(ip);
106	
107	      if (!geo) {
108	        if (isPrivateIp(ip)) {
109	          geo = EMPTY;
110	        } else {
111	          // 1) local cache
112	          const cached = await db.geoCache.findUnique({ where: { ip } }).catch(() => null);
113	          if (cached) {
114	            geo = {
115	              country: cached.country,
116	              region: cached.region,
117	              city: cached.city,
118	              lat: cached.lat,
119	              lng: cached.lng,
120	            };
121	          } else if (external < MAX_EXTERNAL_PER_SWEEP) {
122	            // 2) external lookup (rate-limited)
123	            if (external > 0) await sleep(PACE_MS);
124	            external++;
125	            const fetched = await fetchGeo(ip);
126	            if (fetched) {
127	              geo = fetched;
128	              await db.geoCache
129	                .upsert({
130	                  where: { ip },
131	                  create: { ip, ...fetched },
132	                  update: { ...fetched },
133	                })
134	                .catch((e) => console.error("[geo] cache upsert failed", e));
135	            } else {
136	              // Lookup failed this round — leave the visit for a later sweep.
137	              continue;
138	            }
139	          } else {
140	            // Hit the per-sweep external budget; defer remaining IPs.
141	            continue;
142	          }
143	        }
144	        resolved.set(ip, geo);
145	      }
146	
147	      await db.visit.update({
148	        where: { id: visit.id },
149	        data: {
150	          country: geo.country,
151	          region: geo.region,
152	          city: geo.city,
153	          lat: geo.lat,
154	          lng: geo.lng,
155	          geocoded: true,
156	        },
157	      });
158	      processed++;
159	    } catch (e) {
160	      console.error("[geo] failed to enrich visit", visit.id, e);
161	    }
162	  }
163	
164	  if (processed > 0) {
165	    console.log(`[geo] enriched ${processed} visit(s) (${external} external lookups)`);
166	  }
167	  return { processed, external };
168	}
