1	import { execFile } from "node:child_process";
2	import { promisify } from "node:util";
3	import { db } from "../lib/db";
4	
5	const exec = promisify(execFile);
6	
7	const CHAIN = process.env.NXEON_NAT_CHAIN ?? "NXEON_FWD";
8	
9	async function iptables(args: string[]) {
10	  await exec("iptables", args);
11	}
12	
13	async function ensureChain() {
14	  try {
15	    await iptables(["-t", "nat", "-N", CHAIN]);
16	  } catch {
17	    /* chain exists */
18	  }
19	  // Ensure PREROUTING jumps to our chain exactly once
20	  try {
21	    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", CHAIN]);
22	  } catch {
23	    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", CHAIN]);
24	  }
25	}
26	
27	/** Rebuild the entire NXEON_FWD chain from the database. Idempotent. */
28	export async function syncPortForwards() {
29	  await ensureChain();
30	  await iptables(["-t", "nat", "-F", CHAIN]);
31	
32	  const servers = await db.server.findMany({
33	    where: {
34	      ipAddress: { not: null },
35	      sshPort: { not: null },
36	      status: { notIn: ["SUSPENDED", "DELETING"] },
37	    },
38	    include: { portForwards: true },
39	  });
40	
41	  for (const s of servers) {
42	    await iptables([
43	      "-t", "nat", "-A", CHAIN,
44	      "-p", "tcp", "--dport", String(s.sshPort),
45	      "-j", "DNAT", "--to-destination", `${s.ipAddress}:22`,
46	    ]);
47	    for (const f of s.portForwards) {
48	      await iptables([
49	        "-t", "nat", "-A", CHAIN,
50	        "-p", f.protocol, "--dport", String(f.publicPort),
51	        "-j", "DNAT", "--to-destination", `${s.ipAddress}:${f.guestPort}`,
52	      ]);
53	    }
54	  }
55	}
